// LLM API Kullanımı cheat sheet (OpenAI, Anthropic Claude, Gemini, Ollama; Python ve JavaScript). 12 konu.
import type { Topic } from './types'

export const llmApiGiris: { q: string; a: string }[] = [
  { q: 'API ne demek, LLM API ne demek?', a: 'API, iki programın birbiriyle konuşma kuralıdır (Application Programming Interface). LLM API, senin yazdığın programın bir dil modeline mesaj gönderip cevabını almasını sağlar. ChatGPT arayüzünde sen yazarsın; API\'de kodun yazar ve cevabı yine kodun işler. Böylece yapay zeka kendi uygulamanın bir parçası olur.' },
  { q: 'Bununla ne yapabilirim?', a: 'Uygulamana sohbet kutusu eklemek, gelen e-postaları otomatik sınıflandırmak, faturalardan veri çıkarmak, binlerce yorumu özetlemek, belgeyle konuşan asistan kurmak, modelin senin yazdığın fonksiyonları çağırmasını sağlamak. Arayüzde tek tek yaptığın her şeyi kod toplu ve otomatik yapar.' },
  { q: 'Hangi şirketlerin API\'si var, hangisini seçmeliyim?', a: 'OpenAI (GPT modelleri), Anthropic (Claude), Google (Gemini), Mistral, Groq (çok hızlı açık modeller) ve bilgisayarında çalışan Ollama. Hepsi aynı temel yapıyı kullanır: mesaj listesi gönder, cevap al. Birini öğrenince diğerine geçmek bir saatlik iştir. Bu bölüm örnekleri ağırlıkla Claude ve OpenAI ile verir.' },
  { q: 'Ücretli mi, ne kadar tutar?', a: 'Kullandığın kadar ödersin; birim "token" (kelime parçası). Gönderdiğin metin (girdi) ve aldığın cevap (çıktı) ayrı fiyatlanır, çıktı daha pahalıdır. Küçük modeller büyüklerden 10-50 kat ucuzdur. Deneme için birkaç dolar aylarca yeter; ciddi uygulamada önbellek ve toplu işlem indirimleri vardır. Panelde harcama limiti koymayı unutma.' },
  { q: 'API anahtarı ne, neden bu kadar önemli?', a: 'Sağlayıcının sana verdiği uzun gizli şifre; her istekte kim olduğunu ve kime fatura kesileceğini söyler. Ele geçiren senin paranla model kullanır. Bu yüzden sunucu tarafında .env dosyasında durur, koda ve Git\'e yazılmaz, tarayıcıya veya mobil uygulamaya asla gömülmez; oradaki her şey herkes tarafından okunabilir.' },
  { q: 'Programlama bilmem gerekiyor mu?', a: 'Evet, temel düzeyde: Python veya JavaScript\'te fonksiyon yazmak, bir paketi kurmak, JSON denen veri biçimini tanımak. İleri seviye gerekmez; çoğu çağrı beş satırdır. Örnekler Python ağırlıklıdır; JavaScript karşılıkları aynı mantıktadır. Hiç kod bilmiyorsan Python başlığına bir göz atıp dönmek yeterli.' },
  { q: 'SDK ne demek?', a: 'Software Development Kit: sağlayıcının hazırladığı kütüphane. Ham internet isteği yazmak yerine `client.messages.create(...)` gibi tek bir fonksiyon çağırırsın; anahtarı okuma, hata durumunda tekrar deneme, akışı yönetme gibi işleri SDK halleder. Her sağlayıcının resmi SDK\'sı pip veya npm ile kurulur.' },
  { q: 'Mesaj yapısı nasıl, roller ne?', a: 'Modele bir konuşma geçmişi gönderirsin: her mesajın bir rolü vardır. "system" asistanın kalıcı talimatı, "user" kullanıcının söylediği, "assistant" modelin daha önce söylediği. Model geçmişi hatırlamaz; her istekte tüm konuşmayı yeniden gönderirsin. Bu, API\'nin en çok şaşırtan yanıdır.' },
  { q: 'Streaming ne demek?', a: 'Cevabın tamamı bitince değil, üretildikçe kelime kelime gelmesi. ChatGPT\'de yazının akarak gelmesi budur. Kullanıcı on saniye boş ekrana bakmaz; uzun cevaplarda bağlantı zaman aşımına düşmez. Sohbet uygulamalarında standarttır.' },
  { q: 'Yapılı çıktı ve araç çağırma ne demek?', a: 'Yapılı çıktı: modele "cevabı tam olarak şu alanlarla JSON ver" deyip programın güvenle okuyabileceği veri almak. Araç çağırma: modele senin fonksiyonlarını tanıtmak ("hava durumunu sorgula", "siparişi bul"); model gerektiğinde "şu fonksiyonu şu parametreyle çalıştır" der, sen çalıştırıp sonucu verirsin. Ajanların temeli budur.' },
  { q: 'Model hata verirse, limit aşılırsa ne olur?', a: 'API bazen "çok hızlı istek" (429), bazen sunucu hatası (5xx) döner. SDK\'lar otomatik birkaç kez tekrar dener. Sen de çıktıyı doğrular, başarısızsa sınırlı tekrar dener, bir sağlayıcı çökerse diğerine geçersin. Her çağrıyı kaydetmek (log) sorunları bulmanın tek yoludur.' },
  { q: 'Hangi sırayla öğrenmeliyim?', a: 'Soldaki sıra öğrenme sırasıdır: Kurulum ve İlk Çağrı → Mesaj Yapısı → Parametreler → Streaming → Yapılı Çıktı → Araç Çağırma → Görsel ve Belge → Hata → Maliyet → Çoklu Sağlayıcı → Uygulama Kalıpları. İlk üç konu ile çalışan bir şey yaparsın; gerisi onu sağlam ve ucuz hale getirir.' },
  { q: 'Bu bölümden sonra ne gelir?', a: 'RAG ve Vektör Veritabanı: modele kendi belgelerini okutup onlardan cevap aldırmak. Sonra AI Agent\'lar: araç çağırmayı çok adımlı işlere dönüştürmek. En sonda AI Uygulama Geliştirme: tüm bunları gerçek bir ürüne koymak.' },
]

